void* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsUInt32Number Count = 0;
    cmsUInt32Number RecordLength = 0;
    cmsMLU* mlu = NULL;
    cmsUInt32Number i = 0;
    cmsUInt32Number MaxPos = 0;

    if (!io || !nItems) {
        return NULL;
    }

    if (!cmsReadUInt32Array(io, 1, &Count) || !cmsReadUInt32Array(io, 1, &RecordLength)) {
        return NULL;
    }

    if (Count == 0) {
        *nItems = 1;
        return NULL;
    }

    if (RecordLength != sizeof(cmsUInt16Number) * 2 + sizeof(cmsUInt32Number)) {
        return NULL;
    }

    mlu = (cmsMLU*) cmsMalloc(self->Context, sizeof(cmsMLU));
    if (!mlu) {
        return NULL;
    }

    mlu->nItems = Count;
    mlu->Entry = (cmsMLUEntry*) cmsMalloc(self->Context, Count * sizeof(cmsMLUEntry));
    if (!mlu->Entry) {
        cmsFree(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsUInt16Number Language = 0;
        cmsUInt16Number Country = 0;
        cmsUInt32Number StringLength = 0;
        cmsUInt32Number StringOffset = 0;

        if (!cmsReadUInt16Array(io, 1, &Language) || !cmsReadUInt16Array(io, 1, &Country) || !cmsReadUInt32Array(io, 1, &StringLength) || !cmsReadUInt32Array(io, 1, &StringOffset)) {
            cmsMLUFree(mlu);
            return NULL;
        }

        mlu->Entry[i].Language = Language;
        mlu->Entry[i].Country = Country;
        mlu->Entry[i].StringLength = StringLength;
        mlu->Entry[i].StringOffset = StringOffset;

        if (StringOffset + StringLength > MaxPos) {
            MaxPos = StringOffset + StringLength;
        }
    }

    mlu->Strings = (char*) cmsMalloc(self->Context, MaxPos);
    if (!mlu->Strings) {
        cmsMLUFree(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsUInt32Number StringOffset = mlu->Entry[i].StringOffset;
        cmsUInt32Number StringLength = mlu->Entry[i].StringLength;

        if (!cmsReadMem(io, mlu->Strings + StringOffset, StringLength)) {
            cmsMLUFree(mlu);
            return NULL;
        }
    }

    *nItems = Count;
    return (void*) mlu;
}

void* ReadMLU(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag)
{
    cmsUInt32Number Count, RecordLength;
    cmsMLU* mlu = NULL;
    cmsUInt32Number i;
    cmsUInt16Number Language, Country;
    cmsUInt32Number StringLength, Offset;
    cmsUInt32Number MaxOffset = 0;
    char* StringData = NULL;

    if (!io || !nItems)
        return NULL;

    if (!io->Get16(io, &Language) || !io->Get16(io, &Country) || !io->Get32(io, &Count) || !io->Get32(io, &RecordLength))
        return NULL;

    if (RecordLength < 8 || (RecordLength % 4) != 0)
        return NULL;

    mlu = (cmsMLU*) cmsMalloc(self->ContextID, sizeof(cmsMLU));
    if (!mlu)
        return NULL;

    mlu->Language = Language;
    mlu->Country = Country;
    mlu->Count = Count;
    mlu->RecordLength = RecordLength;

    mlu->Strings = (cmsUInt32Number*) cmsMalloc(self->ContextID, Count * 4);
    if (!mlu->Strings) {
        cmsFree(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        if (!io->Get16(io, &Language) || !io->Get16(io, &Country) || !io->Get32(io, &StringLength) || !io->Get32(io, &Offset)) {
            cmsFree(mlu->Strings);
            cmsFree(mlu);
            return NULL;
        }

        if (Offset + StringLength > MaxOffset)
            MaxOffset = Offset + StringLength;

        mlu->Strings[i] = Offset;
    }

    StringData = (char*) cmsMalloc(self->ContextID, MaxOffset);
    if (!StringData) {
        cmsFree(mlu->Strings);
        cmsFree(mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsUInt32Number pos = mlu->Strings[i];
        cmsUInt32Number len = 0;

        if (i < Count - 1)
            len = mlu->Strings[i + 1] - pos;
        else
            len = MaxOffset - pos;

        if (!io->Read(io, &StringData[pos], len)) {
            cmsFree(StringData);
            cmsFree(mlu->Strings);
            cmsFree(mlu);
            return NULL;
        }
    }

    mlu->Data = StringData;
    *nItems = Count;

    return mlu;
}

void* read_mlu_structure(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsUInt32Number count = 0;
    cmsUInt32Number record_length = 0;
    cmsUInt32Number i = 0;
    cmsMLU* mlu = NULL;
    cmsUInt32Number max_position = 0;
    cmsUInt32Number total_size = 0;

    // Read count and record length from the input stream
    if (!io->GetUInt32(io, &count) || !io->GetUInt32(io, &record_length)) {
        return NULL;
    }

    if (record_length < 6 || record_length > 65535) {
        return NULL; // Invalid record length
    }

    total_size = sizeof(cmsMLU) + count * record_length;

    mlu = (cmsMLU*)calloc(1, total_size);
    if (!mlu) {
        return NULL;
    }

    mlu->Count = count;
    mlu->RecordLength = record_length;

    // Read language and country codes and string data
    for (i = 0; i < count; i++) {
        cmsUInt16Number language[4];
        cmsUInt16Number country[4];
        cmsUInt32Number string_length = 0;

        for (int j = 0; j < 4; j++) {
            if (!io->GetUInt16(io, &language[j]) || !io->GetUInt16(io, &country[j])) {
                free(mlu);
                return NULL;
            }
        }

        if (!io->GetUInt32(io, &string_length)) {
            free(mlu);
            return NULL;
        }

        if (string_length > record_length) {
            free(mlu);
            return NULL;
        }

        max_position = (i + 1) * record_length;

        if (!io->Seek(io, max_position)) {
            free(mlu);
            return NULL;
        }

        if (!io->GetUInt32(io, &string_length)) {
            free(mlu);
            return NULL;
        }

        // Read the actual string data
        char* string_data = (char*)malloc(string_length + 1);
        if (!string_data) {
            free(mlu);
            return NULL;
        }

        if (!io->Read(io, string_data, string_length)) {
            free(string_data);
            free(mlu);
            return NULL;
        }

        string_data[string_length] = '\0';

        // Store the string data in the MLU structure
        mlu->Data[i] = string_data;
    }

    *nItems = count;

    return (void*)mlu;
}

cmsMLU*
ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag)
{
    cmsUInt32Number count = 0;
    cmsUInt32Number recordLen = 0;
    cmsUInt32Number i;
    cmsUInt32Number maxPos = 0;
    cmsUInt16Number* langCountry;
    cmsUInt32Number* lengths;
    cmsUInt32Number* offsets;
    cmsMLU* mlu = NULL;
    cmsUInt8Number* buffer = NULL;
    cmsUInt8Number* strings = NULL;

    if (!io || !nItems)
        return NULL;

    if (!cmsReadUInt32Array(io, 1, &count) || !cmsReadUInt32Array(io, 1, &recordLen)) {
        goto Error;
    }

    if (recordLen != sizeof(cmsUInt16Number) * 2 + sizeof(cmsUInt32Number) * 2) {
        goto Error;
    }

    if (count == 0)
        return NULL;

    if (!(langCountry = (cmsUInt16Number*)_cmsMalloc(self, count * 2 * sizeof(cmsUInt16Number))) ||
        !(lengths = (cmsUInt32Number*)_cmsMalloc(self, count * 2 * sizeof(cmsUInt32Number))) ||
        !(offsets = (cmsUInt32Number*)_cmsMalloc(self, count * 2 * sizeof(cmsUInt32Number)))) {
        goto Error;
    }

    for (i = 0; i < count; i++) {
        if (!cmsReadUInt16Array(io, 2, &langCountry[i * 2]) ||
            !cmsReadUInt32Array(io, 1, &lengths[i]) ||
            !cmsReadUInt32Array(io, 1, &offsets[i])) {
            goto Error;
        }

        if (offsets[i] + lengths[i] > maxPos)
            maxPos = offsets[i] + lengths[i];
    }

    if ((buffer = (cmsUInt8Number*)_cmsMalloc(self, maxPos)) == NULL)
        goto Error;

    if (!cmsReadUInt8Array(io, maxPos, buffer))
        goto Error;

    if ((strings = (cmsUInt8Number*)_cmsMalloc(self, maxPos)) == NULL)
        goto Error;

    for (i = 0; i < maxPos; i++)
        strings[i] = buffer[i];

    mlu = (cmsMLU*)_cmsMalloc(self, sizeof(cmsMLU));
    if (mlu == NULL)
        goto Error;

    mlu->nItems = count;
    mlu->LangCountry = langCountry;
    mlu->Lengths = lengths;
    mlu->Strings = strings;

    *nItems = count;

    _cmsFree(self, buffer);
    return mlu;

Error:
    if (buffer)
        _cmsFree(self, buffer);
    if (langCountry)
        _cmsFree(self, langCountry);
    if (lengths)
        _cmsFree(self, lengths);
    if (offsets)
        _cmsFree(self, offsets);
    if (mlu)
        _cmsFree(self, mlu);
    if (strings)
        _cmsFree(self, strings);

    return NULL;
}

void* ReadMLUFromStream(struct _cms_typehandler_struct* self, cmsIOHANDLER* io, cmsUInt32Number* nItems, cmsUInt32Number SizeOfTag) {
    cmsUInt16Number Count;
    cmsUInt16Number RecordLength;
    cmsMLU* mlu = NULL;
    cmsUInt32Number i;
    cmsUInt32Number MaxPos = 0;

    if (!io || !nItems)
        return NULL;

    if (!cmsRead16Array(io, 1, &Count) || !cmsRead16Array(io, 1, &RecordLength))
        return NULL;

    if (RecordLength == 0 || (cmsUInt32Number)RecordLength > (SizeOfTag - 8) / 2) {
        return NULL; // Invalid record length
    }

    mlu = (cmsUInt8Number*)_cmsMalloc(self, sizeof(cmsMLU));
    if (!mlu)
        return NULL;

    mlu->Count = Count;
    mlu->RecordLength = RecordLength;

    mlu->Entry = (cmsMLUentry*)_cmsMalloc(self, sizeof(cmsMLUentry) * Count);
    if (!mlu->Entry) {
        _cmsFree(self, mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsMLUentry* entry = &mlu->Entry[i];
        cmsUInt16Number LanguageCode;
        cmsUInt16Number CountryCode;
        cmsUInt16Number StringLength;

        if (!cmsRead16Array(io, 1, &LanguageCode) ||
            !cmsRead16Array(io, 1, &CountryCode) ||
            !cmsRead16Array(io, 1, &StringLength)) {
            return NULL;
        }

        entry->LanguageCode = LanguageCode;
        entry->CountryCode = CountryCode;
        entry->StringLength = StringLength;

        MaxPos += StringLength;
    }

    mlu->Strings = (char*)_cmsMalloc(self, MaxPos + 1);
    if (!mlu->Strings) {
        _cmsFree(self, mlu->Entry);
        _cmsFree(self, mlu);
        return NULL;
    }

    for (i = 0; i < Count; i++) {
        cmsMLUentry* entry = &mlu->Entry[i];
        cmsUInt32Number pos = 0;

        for (cmsUInt32Number j = 0; j < i; j++) {
            pos += mlu->Entry[j].StringLength;
        }

        if (!cmsReadMem(io, mlu->Strings + pos, entry->StringLength)) {
            _cmsFree(self, mlu->Strings);
            _cmsFree(self, mlu->Entry);
            _cmsFree(self, mlu);
            return NULL;
        }

        mlu->Strings[pos + entry->StringLength] = '\0';
    }

    *nItems = 1;
    return (void*)mlu;
}
